export const CreateReportBody = zod.object({
  "targetType": zod.enum(['material', 'profile', 'request']),
  "targetId": zod.string().min(1).describe('The target\'s id as a string: a material\'s numeric id (e.g. "42") or a user profile\'s uuid, depending on targetType.'),
  "reason": zod.enum(['copyright', 'inappropriate', 'wrong_info', 'spam', 'other']),
  "details": zod.string().max(createReportBodyDetailsMax).optional(),
  "deviceId": zod.string().max(createReportBodyDeviceIdMax).optional()
})

export const CreateReportResponse = zod.object({
  "id": zod.number().int(),
  "status": zod.enum(['open', 'resolved', 'dismissed'])
})


