/**
 * Deduplicated once per device per file per calendar day (UTC). Signing in is optional (an Authorization bearer header is honored if present) — the X-Device-Id header is what dedup and the "self-download doesn't count" rule key off. A contributor downloading their own material is accepted but never counted.
 * @summary Count a download of a published material
 */
export const RecordMaterialDownloadParams = zod.object({
  "id": zod.coerce.number().int()
})

export const recordMaterialDownloadHeaderXDeviceIdMax = 120;



export const RecordMaterialDownloadHeader = zod.object({
  "X-Device-Id": zod.string().min(1).max(recordMaterialDownloadHeaderXDeviceIdMax)
})

export const RecordMaterialDownloadResponse = zod.object({
  "downloadCount": zod.number().int()
})


/**
 * One per device per file, forever (not per day, unlike downloads). A contributor thanking their own material is accepted but never counted.
 * @summary Send a one-time "شكراً" to a published material's contributor
 */
export const RecordMaterialThanksParams = zod.object({
  "id": zod.coerce.number().int()
})

export const recordMaterialThanksHeaderXDeviceIdMax = 120;



export const RecordMaterialThanksHeader = zod.object({
  "X-Device-Id": zod.string().min(1).max(recordMaterialThanksHeaderXDeviceIdMax)
})

export const RecordMaterialThanksResponse = zod.object({
  "thanksCount": zod.number().int(),
  "alreadyThanked": zod.boolean()
})


/**
 * Respects hideIdentity — returns 404 for a contributor who has chosen to hide their identity, the same as if the account did not exist.
 * @summary Public contributor profile (name, faculty, title, stats, published materials)
 */
export const GetContributorProfileParams = zod.object({
  "id": zod.coerce.string().uuid()
})

export const GetContributorProfileResponse = zod.object({
  "id": zod.string().uuid(),
  "displayName": zod.string(),
  "photoUrl": zod.string().nullable(),
  "facultyNameAr": zod.string().nullable(),
  "title": zod.string().nullable(),
  "publishedCount": zod.number().int(),
  "totalDownloads": zod.number().int(),
  "totalThanks": zod.number().int(),
  "fulfilledRequestsCount": zod.number().int().describe('Published materials by this contributor that fulfilled a "مطلوب" board request — drives the "لبّيت طلب" badge.'),
  "materials": zod.array(zod.object({
  "id": zod.number().int(),
  "titleAr": zod.string(),
  "titleEn": zod.string(),
  "category": zod.enum(['summary', 'lecture-notes', 'previous-exam', 'model-answer', 'revision', 'practice']),
  "subjectId": zod.number().int(),
  "downloadCount": zod.number().int(),
  "thanksCount": zod.number().int(),
  "createdAt": zod.coerce.date()
}))
})


/**
 * Note: there is no explicit start/end date on a semester in this catalog, so the 'semester' scope approximates "current semester" as a rolling trailing window (LEADERBOARD_WINDOW_DAYS, default 120 days) of download activity rather than a true semester boundary.
 * @summary Top 10 contributors in one faculty, by published-material downloads
 */
export const GetLeaderboardQueryParams = zod.object({
  "facultyId": zod.coerce.number().int(),
  "scope": zod.enum(['semester', 'all-time'])
})

export const GetLeaderboardResponse = zod.object({
  "facultyId": zod.number().int(),
  "scope": zod.enum(['semester', 'all-time']),
  "entries": zod.array(zod.object({
  "userId": zod.string().uuid(),
  "displayName": zod.string(),
  "photoUrl": zod.string().nullable(),
  "title": zod.string().nullable(),
  "downloads": zod.number().int(),
  "materialsCount": zod.number().int()
}))
})


